def px(lon, lat): return ((lon + 180) / 360 * W, (90 - lat) / 180 * H)
img = Image.new('L', (W, H), 0); dr = ImageDraw.Draw(img)
for k, pts in P.items(): dr.polygon([px(*p) for p in pts], fill=255)
for k, pts in WATER.items(): dr.polygon([px(*p) for p in pts], fill=0)
base = np.asarray(img).astype(np.float32) / 255

def fnoise(shape, beta, seed):
    r = np.random.default_rng(seed); n = r.standard_normal(shape)
    fy = np.fft.fftfreq(shape[0])[:, None]; fx = np.fft.fftfreq(shape[1])[None, :]
    f = np.sqrt(fx ** 2 + (fy) ** 2); f[0, 0] = 1
    out = np.real(np.fft.ifft2(np.fft.fft2(n) / f ** beta))
    return (out - out.mean()) / out.std()

# litoral ondulado: warp + ruído
n1 = fnoise((H, W), 1.15, 1); n2 = fnoise((H, W), 1.15, 2)
yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
warp = 9.0
bw = ndi.map_coordinates(base, [yy + n1 * warp, (xx + n2 * warp) % W], order=1, mode='wrap')
bw = ndi.gaussian_filter(bw, 2.0, mode='wrap')
detail = fnoise((H, W), 0.9, 3)
land = (bw + detail * 0.10) > 0.5
land = ndi.binary_opening(land, iterations=1)
lat = 90 - (yy + 0.5) / H * 180; lon = (xx + 0.5) / W * 360 - 180
# distância ao litoral
dist_out = ndi.distance_transform_edt(~land); dist_in = ndi.distance_transform_edt(land)

def ell(lo, la, rlo, rla): return np.clip(1 - (((lon - lo) / rlo) ** 2 + ((lat - la) / rla) ** 2), 0, 1)
desert = np.maximum.reduce([ell(10, 22, 30, 10), ell(45, 23, 12, 9), ell(30, 25, 10, 8), ell(133, -25, 14, 9), ell(103, 42, 14, 5),
                            ell(62, 38, 10, 6), ell(-112, 33, 7, 6), ell(20, -24, 6, 5), ell(-70, -24, 3, 8), ell(70, 27, 4, 3)])
hn = fnoise((H, W), 1.0, 4)
desert = np.clip(desert * 1.8 + hn * 0.25 - 0.15, 0, 1)
alat = np.abs(lat)
trop = np.clip(1 - alat / 14, 0, 1) ** 0.7
boreal = np.clip(1 - np.abs(alat - 58) / 9, 0, 1)
tundra = np.clip((alat - 62) / 8, 0, 1)
ice = np.clip((alat - 76) / 5, 0, 1)
gl = ell(-42, 72, 25, 15) * 3; ice = np.maximum(ice, np.clip(gl, 0, 1)); ice = np.where(lat < -62, 1, ice)

def C(*rgb): return np.array(rgb, np.float32) / 255
col = np.zeros((H, W, 3), np.float32)
temperate = C(78, 96, 52); rain = C(30, 62, 28); bor = C(42, 62, 44); tun = C(110, 104, 84); des = C(196, 164, 112); savanna = C(140, 128, 74)
g = temperate[None, None] * np.ones((H, W, 1))
sav = np.clip(1 - np.abs(alat - 15) / 7, 0, 1)[..., None]
g = g * (1 - sav) + savanna * sav
g = g * (1 - trop[..., None]) + rain * trop[..., None]
g = g * (1 - boreal[..., None]) + bor * boreal[..., None]
g = g * (1 - tundra[..., None]) + tun * tundra[..., None]
g = g * (1 - desert[..., None]) + des * desert[..., None]
# relevo: altura fBm e sombreamento
hgt = fnoise((H, W), 1.35, 5) + fnoise((H, W), 0.8, 6) * 0.3
hgt = hgt * np.clip(dist_in / 40, 0, 1)
gy, gx = np.gradient(hgt)
shade = np.clip(1 + (-gx * 0.7 + gy * 0.5) * 9, 0.6, 1.4)
g = g * shade[..., None] * (0.9 + 0.18 * fnoise((H, W), 0.6, 8)[..., None].clip(-1, 1))
g = g * (1 - ice[..., None]) + C(236, 240, 245) * ice[..., None] * (0.92 + 0.06 * shade[..., None])
# oceano
deep = C(5, 18, 44); shallow = C(22, 78, 112)
sh = np.exp(-dist_out / 14.0)[..., None]
o = deep * (1 - sh) + shallow * sh
o = o * (0.92 + 0.08 * fnoise((H, W), 1.1, 9)[..., None].clip(-1, 1))
o = np.where((lat < -64)[..., None] | (lat > 82)[..., None], C(220, 228, 236), o)
L = ndi.gaussian_filter(land.astype(np.float32), 0.7, mode='wrap')[..., None]
out = g * L + o * (1 - L)
srgb = np.clip(out * 255, 0, 255).astype(np.uint8)
# alpha = máscara de oceano (para especular)
spec = ((1 - L[..., 0]) * 255).astype(np.uint8)
day = Image.fromarray(srgb).resize((2048, 1024), Image.LANCZOS)
day.save('/home/claude/claysp/assets/earth_day.jpg', quality=88)
