# nuvens
c1 = fnoise((H // 2, W // 2), 1.25, 11); c2 = fnoise((H // 2, W // 2), 0.75, 12)
yy2, xx2 = np.mgrid[0:H // 2, 0:W // 2].astype(np.float32)
c = ndi.map_coordinates(c1 + c2 * 0.35, [yy2 + fnoise((H // 2, W // 2), 1.4, 13) * 14, (xx2 + fnoise((H // 2, W // 2), 1.4, 14) * 30) % (W // 2)], order=1, mode='wrap')
lat2 = 90 - (yy2 + 0.5) / (H // 2) * 180
band = 0.35 * np.exp(-(lat2 / 8) ** 2) + 0.45 * np.exp(-((np.abs(lat2) - 55) / 12) ** 2) - 0.25 * np.exp(-((np.abs(lat2) - 25) / 8) ** 2)
cl = np.clip((c * 0.5 + band + 0.05) * 1.6, 0, 1) ** 1.4
Image.fromarray((cl * 255).astype(np.uint8)).save('/home/claude/claysp/assets/earth_clouds.jpg', quality=85)
